fn encode(message: Vec<char>) -> Vec<char> {
    // Define a mapping for vowels
    let vowel_mapping: [(char, char); 5] = [
        ('a', 'c'), ('e', 'g'), ('i', 'k'), ('o', 'q'), ('u', 'w'),
    ];
    let vowel_mapping_upper: [(char, char); 5] = [
        ('A', 'C'), ('E', 'G'), ('I', 'K'), ('O', 'Q'), ('U', 'W'),
    ];

    // Create a new vector to hold the result
    let mut result = Vec::with_capacity(message.len());

    for &ch in &message {
        match ch {
            ' ' => result.push(' '), // Space remains unchanged
            'a'..='z' => {
                // Check if it's a vowel
                if let Some(&(_, mapped)) = vowel_mapping.iter().find(|&&(v, _)| v == ch) {
                    // Map and swap case
                    result.push(mapped.to_ascii_uppercase());
                } else {
                    // Swap case for consonants
                    result.push(ch.to_ascii_uppercase());
                }
            }
            'A'..='Z' => {
                // Check if it's a vowel
                if let Some(&(_, mapped)) = vowel_mapping_upper.iter().find(|&&(v, _)| v == ch) {
                    // Map and swap case
                    result.push(mapped.to_ascii_lowercase());
                } else {
                    // Swap case for consonants
                    result.push(ch.to_ascii_lowercase());
                }
            }
            _ => unreachable!(), // According to the problem, this should never happen
        }
    }

    result
}